class ThemeOracleProfileTest {
	@Test
	void unorderedProfileAcceptsProvenUnorderedQueryAndRejectsUnregisteredOrderOrSlice() {
		var profile = ThemeOracleProfile.ADAPTIVE_FILTER_PLACEMENT;
		String query = ThemeQueryCatalog.queryFor(profile.theme(), 0);
		SPARQLParser parser = new SPARQLParser();
		assertThrows(IllegalStateException.class,
				() -> profile.requireSupportedOrder(0,
						parser.parseQuery(query + "\nORDER BY ?probe", null).getTupleExpr()));
		assertThrows(IllegalStateException.class,
				() -> profile.requireSupportedOrder(0, parser.parseQuery(query + "\nLIMIT 1", null).getTupleExpr()));
		assertThrows(IllegalStateException.class, () -> profile.requireSupportedOrder(0, parser.parseQuery(
				"SELECT ?x WHERE { { SELECT ?x WHERE { ?x ?p ?o } ORDER BY ?x } }", null).getTupleExpr()));
		assertDoesNotThrow(() -> profile.requireSupportedOrder(0, parser.parseQuery(query, null).getTupleExpr()));
	}

	@Test
	void registeredLegacyOrdersRequireTheirActualKeysDirectionsAliasAndSlice() {
		SPARQLParser parser = new SPARQLParser();
		String realQ2 = ThemeQueryCatalog.queryFor(Theme.REAL_ESTATE, 2);
		String realQ11 = ThemeQueryCatalog.queryFor(Theme.REAL_ESTATE, 11);
		String socialQ11 = ThemeQueryCatalog.queryFor(Theme.SOCIAL_MEDIA, 11);
		assertDoesNotThrow(() -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery(realQ2, null).getTupleExpr()));
		assertDoesNotThrow(() -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(11,
				parser.parseQuery(realQ11, null).getTupleExpr()));
		assertDoesNotThrow(() -> ThemeOracleProfile.SOCIAL_MEDIA.requireSupportedOrder(11,
				parser.parseQuery(socialQ11, null).getTupleExpr()));
		assertThrows(IllegalStateException.class, () -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery(realQ2.replace("LIMIT 25", "LIMIT 24"), null).getTupleExpr()));
		assertThrows(IllegalStateException.class, () -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery(realQ2.replace("BIND(?price AS ?sortKey)", "BIND(?p AS ?sortKey)"), null)
						.getTupleExpr()));
		assertThrows(IllegalStateException.class, () -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery(realQ2 + "\nOFFSET 1", null).getTupleExpr()));
		assertThrows(IllegalStateException.class, () -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery("SELECT ?p ?price WHERE { { SELECT ?p ?price WHERE { ?p <urn:price> ?price . "
						+ "BIND(?price AS ?sortKey) } } } ORDER BY DESC(?sortKey) ?p LIMIT 25", null).getTupleExpr()));
		assertThrows(IllegalStateException.class, () -> ThemeOracleProfile.SOCIAL_MEDIA.requireSupportedOrder(11,
				parser.parseQuery(socialQ11.replace("ORDER BY ?root ?followed ?post",
						"ORDER BY ?root ?post ?followed"), null).getTupleExpr()));
		assertThrows(IllegalStateException.class, () -> ThemeOracleProfile.SOCIAL_MEDIA.requireSupportedOrder(11,
				parser.parseQuery("SELECT ?root ?followed ?post WHERE { { SELECT ?root ?followed ?post WHERE { "
						+ "?root ?followed ?post } ORDER BY ?root ?followed ?post } }", null).getTupleExpr()));
	}

	@Test
	void registeredOrderRequiresItsLimitOnTheResultOrderPath() {
		String nestedLimitQuery = """
				PREFIX re: <http://example.com/theme/realestate/>
				SELECT ?p ?price ?optRating WHERE {
				  {
				    SELECT ?p ?price WHERE { ?p a re:Property ; re:price ?price . }
				    LIMIT 25
				  }
				  OPTIONAL { ?p re:energyRating ?optRating . }
				  FILTER(?optRating != "G" || !BOUND(?optRating))
				  BIND(?price AS ?sortKey)
				}
				ORDER BY DESC(?sortKey) ?p
				""";
		SPARQLParser parser = new SPARQLParser();
		String nestedDistinctLimitQuery = nestedLimitQuery.replace("SELECT ?p ?price WHERE",
				"SELECT DISTINCT ?p ?price WHERE");
		String nestedWrongLimitQuery = nestedLimitQuery.replace("LIMIT 25", "LIMIT 24");
		String nestedOffsetQuery = nestedLimitQuery.replace("LIMIT 25", "LIMIT 25 OFFSET 1");
		String nestedMultipleLimitQuery = """
				PREFIX re: <http://example.com/theme/realestate/>
				SELECT ?p ?price ?optRating WHERE {
				  {
				    SELECT ?p ?price WHERE {
				      { SELECT ?p ?price WHERE { ?p a re:Property ; re:price ?price . } LIMIT 25 }
				    }
				    LIMIT 25
				  }
				  OPTIONAL { ?p re:energyRating ?optRating . }
				  FILTER(?optRating != "G" || !BOUND(?optRating))
				  BIND(?price AS ?sortKey)
				}
				ORDER BY DESC(?sortKey) ?p
				""";
		String nestedWithOuterLimitQuery = nestedLimitQuery + "\nLIMIT 25";
		String topLevelDistinctQuery = ThemeQueryCatalog.queryFor(Theme.REAL_ESTATE, 2)
				.replace("SELECT ?p ?price ?optRating WHERE",
						"SELECT DISTINCT ?p ?price ?optRating ?sortKey WHERE");
		assertDoesNotThrow(() -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery(ThemeQueryCatalog.queryFor(Theme.REAL_ESTATE, 2), null).getTupleExpr()));
		assertDoesNotThrow(() -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery(topLevelDistinctQuery, null).getTupleExpr()));
		assertThrows(IllegalStateException.class, () -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery(nestedLimitQuery, null).getTupleExpr()), "a sole nested slice cannot prove result order");
		assertThrows(IllegalStateException.class,
				() -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
						parser.parseQuery(nestedDistinctLimitQuery, null).getTupleExpr()),
				"wrappers around a nested slice do not place it on the result-order path");
		assertThrows(IllegalStateException.class, () -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery(nestedWrongLimitQuery, null).getTupleExpr()));
		assertThrows(IllegalStateException.class, () -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery(nestedOffsetQuery, null).getTupleExpr()));
		assertThrows(IllegalStateException.class, () -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery(nestedMultipleLimitQuery, null).getTupleExpr()));
		assertThrows(IllegalStateException.class, () -> ThemeOracleProfile.REAL_ESTATE.requireSupportedOrder(2,
				parser.parseQuery(nestedWithOuterLimitQuery, null).getTupleExpr()),
			"a valid outer slice does not legitimize an additional nested slice");
	}

	@Test
	void formatAndThemeResolveOnlyRegisteredContracts() {
		ThemeOracleProfile adaptive = ThemeOracleProfile.ADAPTIVE_FILTER_PLACEMENT;
		ThemeOracleProfile data = ThemeOracleProfile.DATA_TRANSFORMATION;
		assertEquals(adaptive.format(), data.format(), "generic format is shared by multiple themes");
		assertEquals(adaptive, ThemeOracleProfile.forBundle(adaptive.format(), adaptive.theme().name()));
		assertEquals(data, ThemeOracleProfile.forBundle(data.format(), data.theme().name()));
		assertEquals(ThemeOracleProfile.REAL_ESTATE,
				ThemeOracleProfile.forBundle(ThemeOracleProfile.REAL_ESTATE.format(), null));
		assertThrows(IllegalArgumentException.class, () -> ThemeOracleProfile.forBundle(adaptive.format(), null));
		assertThrows(IllegalArgumentException.class,
				() -> ThemeOracleProfile.forBundle(adaptive.format(), Theme.SOCIAL_MEDIA.name()));
		assertThrows(IllegalArgumentException.class, () -> ThemeOracleProfile.forTheme(Theme.MEDICAL_RECORDS));
		assertTrue(adaptive.orders().isEmpty());
		assertThrows(UnsupportedOperationException.class, () -> adaptive.orders().clear());
	}

	@Test
	void orderContractsRejectInvalidPathsAndKeys() {
		assertThrows(IllegalArgumentException.class, () -> new OrderSpec(-1, "order.json", OrderKind.KEY_GROUPS,
				List.of("key")));
		assertThrows(IllegalArgumentException.class, () -> new OrderSpec(0, "../order.json", OrderKind.KEY_GROUPS,
				List.of("key")));
		assertThrows(IllegalArgumentException.class,
				() -> new OrderSpec(0, "..", OrderKind.KEY_GROUPS, List.of("key")));
		assertThrows(IllegalArgumentException.class,
				() -> new OrderSpec(0, "order.json", OrderKind.KEY_GROUPS, List.of("key", "key")));
	}

	@Test
	void keyGroupContractRejectsUnprovedBlankNodeAndNestedTermIdentity() {
		var vf = SimpleValueFactory.getInstance();
		var spec = ThemeOracleProfile.SOCIAL_MEDIA.order(11).orElseThrow();
		var iri = vf.createIRI("urn:example");
		assertThrows(IllegalStateException.class,
				() -> spec.requireSupportedGroupKeys(List.of(iri, vf.createBNode("x"), iri)));
		assertThrows(IllegalStateException.class, () -> spec.requireSupportedGroupKeys(
				List.of(iri, vf.createTripleTerm(iri, iri, vf.createBNode("x")), iri)));
		assertThrows(IllegalStateException.class,
				() -> spec.requireSupportedGroupKeys(List.of(iri, vf.createLiteral("value"), iri)));
		assertDoesNotThrow(() -> spec.requireSupportedGroupKeys(Arrays.asList(iri, null, iri)));
	}

	@Test
	void unorderedProfileRejectsNondeterministicProjectionWithoutPermittedResultPolicy() {
		var profile = ThemeOracleProfile.ADAPTIVE_FILTER_PLACEMENT;
		SPARQLParser parser = new SPARQLParser();
		for (String query : List.of(
				"SELECT (SAMPLE(?x) AS ?value) WHERE { ?x ?p ?o }",
				"SELECT (GROUP_CONCAT(STR(?x)) AS ?value) WHERE { ?x ?p ?o }",
				"SELECT REDUCED ?x WHERE { ?x ?p ?o }")) {
			assertThrows(IllegalStateException.class,
					() -> profile.requireSupportedOrder(0, parser.parseQuery(query, null).getTupleExpr()), query);
		}
	}
}
